    "api_secret = 'xxxx'\n",
    "client = Client(api_key, api_secret)\n",
    "utc_minus_5 = timezone(timedelta(hours=-5))\n",
    "# Define symbol and interval\n",
    "symbol = \"BTCUSDT\"\n",
    "interval = Client.KLINE_INTERVAL_15MINUTE  # 15-minute timeframe\n",
    "start_date_utc_5 = datetime(2024, 8, 15, 0, 0, 0, tzinfo=utc_minus_5) \n",
    "end_date_utc_5 = datetime(2024, 12,7, 23, 59, 59, tzinfo=utc_minus_5)\n",
    "# Define start and end dates (Adjusted for Futures Market in UTC-5)\n",
    "utc_minus_5 = timezone(timedelta(hours=-5))\n",
    "start_date = start_date_utc_5- timedelta(minutes=400*15)\n",
    "end_date = end_date_utc_5\n",
    "\n",
    "\n",
    "\n",
    "# Convert to UTC timestamps in milliseconds\n",
    "start_time_ms = int(start_date.astimezone(timezone.utc).timestamp() * 1000) \n",
    "end_time_ms = int(end_date.astimezone(timezone.utc).timestamp() * 1000)\n",
    "\n",
    "# Column names for kline data\n",
    "columns = ['open_time', 'open', 'high', 'low', 'close', 'volume', 'close_time', \n",
    "           'qav', 'num_trades', 'taker_base_vol', 'taker_quote_vol', 'ignore']\n",
    "\n",
    "def fetch_btc_data():\n",
    "    \"\"\"Fetch BTCUSDT historical close prices for 15-minute intervals.\"\"\"\n",
    "    all_data = []\n",
    "    current_start_time = start_time_ms\n",
    "\n",
    "    while current_start_time < end_time_ms:\n",
    "        data = pd.DataFrame(client.futures_klines(\n",
    "            symbol=symbol, interval=interval, startTime=current_start_time, endTime=end_time_ms, limit=500\n",
    "        ))\n",
    "\n",
    "        if data.empty:\n",
    "            break  # Stop if no data is returned\n",
    "\n",
    "        data.columns = columns  # Assign column names\n",
    "        data = data[['open_time', 'close',\"volume\"]]  # Select only open_time and close price\n",
    "        data['open_time'] = pd.to_datetime(data['open_time'], unit='ms')  # Convert to datetime\n",
    "        all_data.append(data)\n",
    "        data['open_time'] = pd.to_datetime(data['open_time'], unit='ms')\n",
    "        data['close'] = pd.to_numeric(data['close'])\n",
    "        data['volume'] = pd.to_numeric(data['volume'])\n",
    "\n",
    "        # Update `current_start_time` to last close time to get the next batch\n",
    "        last_close_time = int(data.iloc[-1]['open_time'].timestamp() * 1000)\n",
    "        if last_close_time == current_start_time:\n",
    "            break  # Prevent infinite loop if no new data\n",
    "        current_start_time = last_close_time + 1\n",
    "\n",
    "    return pd.concat(all_data, ignore_index=True) if all_data else pd.DataFrame()\n",
