    "import numpy as np\n",
    "import pandas as pd\n",
    "import matplotlib.pyplot as plt\n",
    "import cvxpy as cp  # Make sure you have cvxpy installed!\n",
    "\n",
    "# --- Step 1: Prepare joint segments ---\n",
    "joint_segments = []\n",
    "segment_times = []\n",
    "\n",
    "for start in range(0, len(btc_data) - h1 + 1, step):\n",
    "    btc_seg = btc_data['log_return'].iloc[start:start+h1].values\n",
    "    eth_seg = eth_data['log_return'].iloc[start:start+h1].values\n",
    "    joint_seg = np.vstack((btc_seg, eth_seg))  # shape (2, h1)\n",
    "    joint_segments.append(joint_seg)\n",
    "    segment_times.append(btc_data.index[start+h1-1])  # take end time of segment\n",
    "\n",
    "joint_segments = np.array(joint_segments)\n",
    "\n",
    "# --- Step 2: Mean, Std, Correlation per segment ---\n",
    "means = []\n",
    "stds = []\n",
    "cors = []\n",
    "\n",
    "for seg in joint_segments:\n",
    "    btc_seg, eth_seg = seg\n",
    "    mean_btc = np.mean(btc_seg)\n",
    "    mean_eth = np.mean(eth_seg)\n",
    "    std_btc = np.std(btc_seg)\n",
    "    std_eth = np.std(eth_seg)\n",
    "    corr = np.corrcoef(btc_seg, eth_seg)[0, 1]\n",
    "    \n",
    "    means.append([mean_btc, mean_eth])\n",
    "    stds.append([std_btc, std_eth])\n",
    "    cors.append(corr)\n",
    "\n",
    "means = np.array(means)\n",
    "stds = np.array(stds)\n",
    "cors = np.array(cors)\n",
    "\n",
    "# --- Step 3: Assign clusters (already done with your btc_labels and eth_labels) ---\n",
    "\n",
    "# Here, for simplicity, let's combine btc_labels and eth_labels into a joint cluster assignment:\n",
    "# (you can refine later, but let's keep it simple first)\n",
    "joint_labels = (btc_labels + eth_labels) // 2  # rough but practical combination\n",
    "\n",
    "# --- Step 4: Estimate cluster statistics ---\n",
    "cluster_info = {}\n",
    "\n",
    "for cluster_id in np.unique(joint_labels):\n",
    "    cluster_idx = (joint_labels == cluster_id)\n",
    "    cluster_means = means[cluster_idx]\n",
    "    cluster_stds = stds[cluster_idx]\n",
    "    cluster_cors = cors[cluster_idx]\n",
    "    \n",
    "    avg_mean = cluster_means.mean(axis=0)\n",
    "    avg_std = cluster_stds.mean(axis=0)\n",
    "    avg_corr = cluster_cors.mean()\n",
    "    \n",
    "    cluster_info[cluster_id] = {\n",
    "        'mean': avg_mean,\n",
    "        'std': avg_std,\n",
    "        'corr': avg_corr\n",
    "    }\n",
    "\n",
    "# --- Step 5: MPT Optimization per cluster ---\n",
    "def optimize_portfolio(mean_returns, cov_matrix, target_return=0.0005):\n",
    "    w = cp.Variable(2)\n",
    "    objective = cp.Minimize(cp.quad_form(w, cov_matrix))\n",
    "    constraints = [\n",
    "        cp.sum(w) == 1,\n",
    "        mean_returns @ w >= target_return\n",
    "    ]\n",
    "    prob = cp.Problem(objective, constraints)\n",
    "    prob.solve()\n",
    "    if w.value is not None:\n",
    "        return w.value\n",
    "    else:\n",
    "        return np.array([0.5, 0.5])  # fallback to equal weights\n",
    "\n",
    "# Precompute optimized weights per cluster\n",
    "optimized_weights = {}\n",
    "for cluster_id, stats in cluster_info.items():\n",
    "    mean = stats['mean']\n",
    "    std = stats['std']\n",
    "    corr = stats['corr']\n",
    "    \n",
    "    cov_matrix = np.array([\n",
    "        [std[0]**2, corr * std[0] * std[1]],\n",
    "        [corr * std[0] * std[1], std[1]**2]\n",
    "    ])\n",
    "    \n",
    "    weights = optimize_portfolio(mean, cov_matrix)\n",
    "    optimized_weights[cluster_id] = weights\n",
    "\n",
    "# --- Step 6: Simulate Trading ---\n",
    "btc_returns = btc_data['log_return'].iloc[h1-1:]\n",
    "eth_returns = eth_data['log_return'].iloc[h1-1:]\n",
    "\n",
    "portfolio_cb = [1]\n",
    "portfolio_simple = [1]\n",
    "\n",
    "for i in range(len(btc_returns)):\n",
    "    if i >= len(joint_labels):\n",
    "        break\n",
    "        \n",
    "    label = joint_labels[i]\n",
    "    weights = optimized_weights.get(label, np.array([0.5, 0.5]))\n",
    "    \n",
    "    ret_cb = weights[0] * btc_returns.iloc[i] + weights[1] * eth_returns.iloc[i]\n",
    "    ret_simple = 0.5 * btc_returns.iloc[i] + 0.5 * eth_returns.iloc[i]\n",
    "    \n",
    "    portfolio_cb.append(portfolio_cb[-1] * (1 + ret_cb))\n",
    "    portfolio_simple.append(portfolio_simple[-1] * (1 + ret_simple))\n",
    "\n",
    "# Align your timestamps to match one point per segment\n",
    "aligned_index = btc_returns.index[::step][: len(portfolio_cb) - 1]\n",
    "\n",
    "plt.figure(figsize=(12,6))\n",
    "plt.plot(aligned_index, portfolio_cb[1:], label='Cluster-Based Portfolio', color='blue')\n",
    "plt.plot(aligned_index, portfolio_simple[1:], label='Simple 50-50 Portfolio', color='orange', linestyle='--')\n",
    "\n",
    "plt.title('BTC-ETH Cluster-Based Strategy vs Simple 50-50 Buy-and-Hold')\n",
    "plt.xlabel('Date')\n",
    "plt.ylabel('Portfolio Value')\n",
    "plt.legend()\n",
    "plt.grid(True)\n",
    "plt.show()\n",
    "\n"
